// Só entra o que NÃO existe na farmácia de jeito nenhum: zerado e sem
// estoque em outro cadastro do mesmo nome nem em outra marca equivalente
// (estoque_irmaos vem da query já somando os dois). Qualquer unidade em
// outro cadastro tira da lista — pedido do gestor em 29/09/2026 (antes
// era só com 7+ dias de cobertura, e os cobertos iam num rodapé).
// Espelha a lista "Estoque zerado — giro alto" da aba Compras no app.
const linhas = $input.all().map((i) => i.json).filter((p) => !(Number(p.estoque_irmaos) > 0));
if (linhas.length === 0) {
  return [];
}
const hojeLabel = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });

const blocos = linhas.map((p, i) => {
  const q = Math.round(Number(p.quantidade_vendida_30d));
  return `${i + 1}. ${p.nome_produto} (cód. ${p.codigo_produto}) — ${q} ${q === 1 ? 'vendido' : 'vendidos'} em 30d`;
});

const mensagem = `📦 *Estoque zerado — produtos de giro alto*\n📅 ${hojeLabel}\n\n${blocos.join('\n')}\n\nRepor com prioridade — são os produtos que mais vendem e não têm nenhuma unidade na farmácia (nem em outro cadastro ou marca equivalente).`;

return [{ json: { mensagem } }];
